pragma solidity ^0.8.20;


contract SubscriptionManager {
    address public owner;
    IERC20 public usdcToken;
    uint256 public monthlyFee = 50 * 10**6; // 50 USDC (USDC has 6 decimals)

    mapping(address => uint256) public subscriptions; // Expiration timestamp
    mapping(address => uint256) public userBalances; // User deposits
    mapping(address => bool) public freeUsers; // Free access users

    event SubscriptionPaid(address indexed user, uint256 expiresAt);
    event FundsWithdrawn(address indexed user, uint256 amount);
    event FreeAccessGranted(address indexed user);
    event FreeAccessRevoked(address indexed user);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not contract owner");
        _;
    }

    constructor(address _usdcAddress) {
        require(_usdcAddress != address(0), "Invalid USDC address");
        usdcToken = IERC20(_usdcAddress);
        owner = msg.sender;
    }

    function grantFreeAccess(address user) external onlyOwner {
        freeUsers[user] = true;
        emit FreeAccessGranted(user);
    }

    function revokeFreeAccess(address user) external onlyOwner {
        freeUsers[user] = false;
        emit FreeAccessRevoked(user);
    }

    function subscribe(uint256 amount) external {
        require(!freeUsers[msg.sender], "You have free access, no payment required");
        require(amount >= monthlyFee, "Insufficient payment");
        require(usdcToken.transferFrom(msg.sender, address(this), amount), "Payment failed");

        uint256 newExpiration = block.timestamp + 30 days;
        subscriptions[msg.sender] = newExpiration;
        userBalances[msg.sender] += amount;

        emit SubscriptionPaid(msg.sender, newExpiration);
    }

    function checkSubscription(address user) external view returns (bool) {
        if (user == owner || freeUsers[user]) {
            return true; // Owner & free users always have access
        }
        return block.timestamp < subscriptions[user];
    }

    function depositFunds(uint256 amount) external {
        require(amount > 0, "Deposit must be greater than zero");
        require(usdcToken.transferFrom(msg.sender, address(this), amount), "Deposit failed");

        userBalances[msg.sender] += amount;
    }

    function withdrawFunds(uint256 amount) external {
        require(userBalances[msg.sender] >= amount, "Insufficient funds");
        userBalances[msg.sender] -= amount;
        require(usdcToken.transfer(msg.sender, amount), "Withdraw failed");

        emit FundsWithdrawn(msg.sender, amount);
    }

    function ownerWithdrawFunds() external onlyOwner {
        uint256 balance = usdcToken.balanceOf(address(this));
        require(balance > 0, "No funds to withdraw");
        require(usdcToken.transfer(owner, balance), "Withdraw failed");
    }
}
